<template>
    <div class="page">
        <app-header :title='tits' :istop="num"></app-header>
        <div class="main">
            <van-form >
                <div class="formCol">
                    <div class="item">
                        <div class="label">{{appStore.rolelist[userInfo.layer-1] }}账号</div>
                        <div class="item-rt">
                            {{ userInfo.paccount }}
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">会员账号</div>
                        <div class="item-rt">
                            {{ userInfo.account }}
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">登录密码</div>
                        <div class="item-rt">
                            <input  v-model="ruleForm.passwd" :rules="rules.passwd"  class="addInput" />
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">会员昵称</div>
                        <div class="item-rt">
                            <input  v-model="ruleForm.nickName" :rules="rules.nickName" class="addInput" />
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">状态</div>
                        <div class="item-rt">
                            <van-radio-group class="checkbox" v-model="ruleForm.status" direction="horizontal" placeholder="请选择状态">
                                <van-radio :name="1" icon-size="16px">启用</van-radio>
                                <van-radio :name="2" icon-size="16px">禁用</van-radio>
                                <van-radio :name="3" icon-size="16px">冻结</van-radio>
                            </van-radio-group>
                        </div>
                    </div>
                    <div class="item" style="align-items: baseline">
                        <div class="label">{{ userInfo.mode == 1 ? '信用' : '现金' }}额度</div>
                        <div class="item-rt">
                            <p style="width:240px;display:flex;align-items:center">
                                <span style="margin-right:5px">{{userTime.isDot(userInfo.cash - userInfo.cashUsed) }}</span>
                                <span @click="openDialog(userInfo,'showDialog2',2)" class="blue pointer">修改</span>
                            </p>
                        </div>
                    </div>
                    <div class="item">
                        <div class="label">开放盘口</div>
                        <div class="item-rt">
                            <van-radio-group disabled v-model="ruleForm.handicap" direction="horizontal" icon-size="16px">
                                <template v-for="iten in userInfo.phandicapList">
                                    <van-radio icon-size="16px" :key="iten" v-if="iten == 1" :name="1">A盘</van-radio>
                                    <van-radio icon-size="16px" :key="iten" v-if="iten == 2" :name="2">B盘</van-radio>
                                    <van-radio icon-size="16px" :key="iten" v-if="iten == 3" :name="3">C盘</van-radio>
                                    <van-radio icon-size="16px" :key="iten" v-if="iten == 4" :name="4">D盘</van-radio>
                                </template>
                            </van-radio-group>
                        </div>
                    </div>
                    <div class="item" style="align-items:start">
                        <div class="label">游戏显示</div>
                        <div class="item-rt" style="padding-top:5px;">
                            <van-checkbox-group class="checkbox" direction="horizontal" v-model="ruleForm.lotlist">
                                <template v-for="(item,index) in yxlist" :key="index + 1" >
                                    <van-checkbox style="margin-bottom:5px;width:115px" v-if="item.show" :disabled="item.show" icon-size="14px" :name="item.lotteryId" shape="square">{{ item.lotteryName }}</van-checkbox>
                                    <van-checkbox style="margin-bottom:5px;width:115px" v-else @click="selctLottry(item)" icon-size="14px" :name="item.lotteryId" shape="square">{{ item.lotteryName }}</van-checkbox>
                                </template>
                            </van-checkbox-group>
                        </div>
                    </div>
                </div>
                <div class="mixSet">
                    <div class="title blue">占成设置</div>
                    <div class="mixCon">
                        <div style="overflow:auto;padding-bottom:10px">
                            <table style="width:100%">
                                <thead>
                                    <tr>
                                        <th>类型</th>
                                        <th>代理占成</th>
                                        <th>可分配占成</th>
                                    </tr>
                                </thead>
                                <tbody v-if="ruleForm.opcpList.length > 0">
                                    <tr>
                                        <td style="color:#4768B0">快捷设置</td>
                                        <td>
                                            <div class="field">
                                                <van-field type="digit" input-align="center" style="width:90px;" @change="copyOccupy" v-model.number="ruleForm.share" @keyup.native="check_count" class="field input"
                                                           size="mini"></van-field>
                                                <span style="width:60px;display:inline-block"></span>
                                            </div>
                                        </td>
                                        <td></td>
                                    </tr>
                                    <tr v-for="(item,index) in ruleForm.opcpList" :key="item.lotteryId" :class="(index % 2 == 0) ? 'eve' : 'old'">
                                        <td><span v-if="item.isChange == 1" class="red">[预设]</span>{{ item.lotteryName }}</td>
                                        <td>
                                            <div class="field">
                                                <span v-if="item.isChange == 1" class="red" style="margin-right:5px">{{ item.oldShare }}</span>
                                                <van-stepper :show-minus="false" :show-plus="false" :min="item.pminShare" :max="item.pmaxShare" @keyup.native="check_count" integer
                                                             v-model="item.share"></van-stepper>
                                                <span style="width:60px;display:inline-block">({{ item.pminShare }}至{{ item.pmaxShare }})</span>
                                            </div>
                                        </td>
                                        <td>{{ item.pmaxShare }}</td>
                                    </tr>
                                </tbody>
                            </table>
                        </div>
                        <div v-if="userInfo.isChange == 1" class="center red" style="padding:5px 10px;font-size:12px">
                            当前用户已下注，（预设）占成金额将在明天开盘生效
                        </div>
                        <div class="fobtn">
                            <div class="fobcanl" @click="cancelForm()">取消</div>
                            <div class="fobmits" @click="onSubmit">确定</div>
                        </div>
                    </div>
                </div>
            </van-form>
        </div>
        <van-popup v-model="showDialog2" :overlay="false" position="bottom" class="popTop">
            <div class="pop-line">
                <div class="pop-lines" @click="showDialog2 = false">
                    <div class="pop-list-line"></div>
                </div>
                <div class="pop-head">
                    <div class="pop-head-t">{{ userInfo.account }}# 额度修改</div>
                    <div @click="showDialog2=false"" class="pop-head-img">关闭</div>
                </div>
            </div>
            <div style="padding: 10px">
                <van-form @submit="confirmAmount('cashAmount')">
                    <div class="je-list">
                        <div class="je-list-left">账号</div>
                        <div class="je-list-right bu">{{ userInfo.account }}</div>
                    </div>
                    <div class="je-list">
                        <div class="je-list-left">{{ userInfo.mode == 1 ? '信用' : '现金' }}额度</div>
                        <div class="je-list-right gr">{{userTime.isDot(userInfo.cash - userInfo.cashUsed) }}</div>
                        <div class="je-list-btn" @click="extractAll('cashAmount')">全部提取</div>
                    </div>
                    <div class="je-list">
                        <div class="je-list-left">余额</div>
                        <div class="je-list-right">{{ userTime.isDot(upLevelAmount) }}</div>
                    </div>
                    <div class="je-list">
                        <div class="je-list-left">类型</div>
                        <div class="je-list-right">
                            <van-radio-group v-model="dataParams.ops" direction="horizontal" icon-size="16px">
                                <van-radio :name="1">存款</van-radio>
                                <van-radio :name="2">提款</van-radio>
                            </van-radio-group>
                        </div>
                    </div>
                    <div class="je-list">
                        <div class="je-list-left">金额</div>
                        <div class="je-list-right">
                            <van-field @input="changeOn" v-model="dataParams.amount" type="digit" :rules="[{ required: true, message: '请输入金额' }]"
                                       class="input" size="small" style="width:90px;"></van-field>
                        </div>
                        <div class="je-list-ts" v-if="beyond">超出上级限制的额度</div>
                    </div>
                    <div class="je-list" v-if="dataParams.amount">
                        <div class="je-list-ts" style="text-align: center;font-weight: bold;color:#323233">{{ number2china }}</div>
                    </div>
                    <div style="margin: 16px;">
                        <van-button round block :disabled="store.state.loading" type="info" native-type="submit">提交</van-button>
                    </div>
                </van-form>
            </div>
        </van-popup>
        <van-dialog v-model="showdio" title="警告" show-cancel-button @confirm="qdan">
            <div style="margin:15px;font-size:14px"><span>将抽取所有下线代理和会员额度,</span><span style="color: red">&nbsp;信用额度返还上级,现金额度系统回收。</span></div>
        </van-dialog>
        <van-popup v-model="lottShow" :overlay="false" position="bottom" class="popTop">
            <div class="pop-line">
                <div class="pop-lines" @click="lottShow = false">
                    <div class="pop-list-line"></div>
                </div>
                <div class="pop-head">
                    <div class="pop-head-t">新增/删除游戏</div>
                    <div @click="lottShow=false"" class="pop-head-img">关闭</div>
                </div>
            </div>
            <div style="padding: 10px;color:#fff">
                <div style="color: #353f60;">步骤1:每次只可添加一个游戏。</div>
                <div style="color: #353f60;">步骤2:默认不占成，请设置好成数。</div>
                <div style="color: #353f60;">步骤3:当天有帐，不能删除游戏，隔天才能操作此功能。</div>
                <div style="color: red;">步骤4:点击(保存)按钮,游戏即添加完成,如有异议,请点击(关闭)按钮。</div>
                <div style="color: red;">新增游戏,切记设置成数,否则引起任何占成问题都由自身承担全部责任!</div>
                <div class="bt-list">
                    <div class="tip-bt" @click="lottSure">保存</div>
                    <div class="tip-bt qx" @click="lottDialog">关闭</div>
                </div>
            </div>
        </van-popup>
    </div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter,useRoute } from 'vue-router'
import { useUserStore } from '@/store/user'
import { useAppStore } from '@/store/index'
import { useTimeUtils } from '@/utils/time'
import useMd5 from '@/utils/useMd5'
import { showToast, showConfirmDialog,showLoadingToast } from 'vant'
import nzhcn from "nzh/cn";

// 路由和状态管理
const router = useRouter()
const route = useRoute()
const userStore = useUserStore()
const appStore = useAppStore()
const userTime = useTimeUtils()
const md5 = useMd5();
const num = ref(3)
const tits = ref('修改会员')
const props = defineProps(['id'])

// ==================== 数据定义 ====================
const userInfo = ref({
    paccount: '',
    account: '',
    cash: 0,
    cashUsed: 0,
    mode: 1,
    layer: 0,
    pid: '',
    id: '',
    handicapList: [],
    phandicapList: [],
    lotteryList: [],
    lotteryList1: [],
    role: 0,
    status: 1,
    isChange: 0
})

const userInfoList = ref({})

const dataParams = reactive({
    ops: '',
    type: '',
    accountId: '',
    amount: ''
})

const selectUserInfo = reactive({
    credit: '',
    cash: '',
    isShowCanUse: 2,
    canUseLimit: '',
    username: ''
})

const lotId = ref("")
const lottShow = ref(false)
const lottDisable = ref(false)
const showdio = ref(false)
const isA = ref(false)
const isB = ref(false)
const isC = ref(false)
const isD = ref(false)
const beyond = ref(false)
const userPassName = ref('')
const upLevelAmount = ref(0)
const showDialog1 = ref(false)
const showDialog2 = ref(false)
const showDialog3 = ref(false)
const changePword = ref(false)
const showPword = ref(false)
const yxlist = ref([])

const ruleForm = reactive({
    id: props.id,
    nickName: '',
    status: '',
    passwd: '',
    handicapList: [],
    handicap: 1,
    lotteryList: [],
    lotlist: [],
    opcpList: [],
    share: '',
    account: '',
    mode: 1,
    layer: 0,
    password: '',
    role: 0
})

const loading = ref(false)

// ==================== 验证器函数 ====================
const min = () => (rule, value, callback) => {
    let tt = rule.field.split('.')
    let t1 = ruleForm.opcpList[tt[1]].pminShare
    let t2 = ruleForm.opcpList[tt[1]].pmaxShare
    if (value < 0) {
        callback(new Error('填写的值不能小于最低值!'))
    } else if (value > t1) {
        callback(new Error('填写的值不能大于最高值!'))
    } else if (value > t2) {
        callback(new Error('输入最小值不能大于输入最大值!'))
    } else {
        callback()
    }
}

// ==================== 表单验证规则 ====================
const rules = reactive({
    passwd: [
        { required: true, message: '请填写登录密码', trigger: 'blur' },
        {
            type: 'string',
            pattern: /(?![^a-zA-Z0-9]+$)(?![^a-zA-Z/D]+$)(?![^0-9/D]+$).{6,20}$/,
            message: '密码由6位以上英文、数字组成',
            trigger: 'blur'
        },
    ],
    handicapList: [
        { required: true, message: '请选择开放盘口', trigger: 'change' }
    ],
    upper_hold: [
        { type: 'number', min: 0, message: '只能填写数字', trigger: 'blur' },
        { required: true, message: '请填写最高占成', trigger: 'blur' },
        { validator: min(), trigger: 'blur' }
    ],
})

// ==================== 计算属性 ====================
const number2china = computed(() => {
    if (dataParams.amount * 1 > 0) {
        return nzhcn.encodeS(dataParams.amount)
    }
    return ''
})

const check_count = (e) => {
    let obj = e.target
    if (obj.value != '' && obj.value.substr(0, 1) == '.') {
        obj.value = ""
    }
    let result = (obj.value.toString()).indexOf(".")
    if (result != -1) {
        obj.value = ""
    }
    obj.value = obj.value.replace(/\D/g, '')
}

// ==================== 主要方法 ====================
const copyOccupy = () => {
    ruleForm.opcpList.map(iten => {
        if (ruleForm.share > iten.pminShare) {
            iten.share = ruleForm.share
        } else {
            iten.share = iten.pminShare
        }
    })
}

const isRequired = () => {
    if (!ruleForm.passwd) {
        rules.passwd[0].required = false
    }
}

const selctLottry = (val) => {
    lottShow.value = true
    lotId.value = val.lotteryId
}

const lottDialog = () => {
    lottShow.value = false
    let t = []
    userInfo.value.lotteryList.map(iten => {
        t.push(iten.lotteryId)
    })
    ruleForm.lotlist = t
    lottDisable.value = false
}

const lottSure = () => {
    if (loading.value) {
        return false
    }
    loading.value = true
    setTimeout(() => {
        loading.value = false
    }, 3000)
    
    if (ruleForm.lotlist.length == 0) {
        let t = []
        userInfo.value.lotteryList.map(iten => {
            t.push(iten.lotteryId)
        })
        ruleForm.lotlist = t
        lottShow.value = false
        showToast({
            message: '至少要选择一个游戏',
            className: 'custom-toast',
            duration: 1000  // 自定义显示时间
        });
        return false
    }
    
    let str = {
        id: props.id,
        lotteryId: lotId.value
    }
    
    if (!lottDisable.value) {
        ajax.addLottery(str).then(res => {
            lottShow.value = false
            lottDisable.value = false
            store.state.loading = false
            showToast({
                type: res.code == 200 ? 'success' : 'error',
                message: res.message,
            })
            if (res.code == 200) {
                getUserInfo()
            }
        }).catch(() => {
            lottShow.value = false
            lottDisable.value = false
        })
    }
    
    lottDisable.value = true
    setTimeout(function () {
        lottDisable.value = false
    }, 5000)
}

const closeDialog = () => {
    dataParams.ops = ''
    dataParams.type = ''
    dataParams.accountId = ''
    dataParams.amount = ''
    showDialog1.value = false
    showDialog2.value = false
    showDialog3.value = false
    upLevelAmount.value = 0
}

const openDialog = (items, type, num) => {
    ajax.quotaFind(items.id).then(res => {
        if (res.code == 200) {
            if (type === 'showDialog1') showDialog1.value = true
            if (type === 'showDialog2') showDialog2.value = true
            if (type === 'showDialog3') showDialog3.value = true
            beyond.value = false
            dataParams.accountId = items.id
            dataParams.type = res.data.type
            selectUserInfo.username = items.account
            if (res.data.type == 1) {
                selectUserInfo.credit = res.data.limit
                selectUserInfo.isShowCanUse = res.data.isShowCanUse
                selectUserInfo.canUseLimit = res.data.canUseLimit
            } else {
                selectUserInfo.cash = res.data.limit
                selectUserInfo.isShowCanUse = res.data.isShowCanUse
            }
            upLevelAmount.value = res.data.upLimit
        }
    })
}

const changeOn = () => {
    beyond.value = false
    if (Number(dataParams.amount) > Number(upLevelAmount.value) && dataParams.ops == 1) {
        beyond.value = true
    } else if (showDialog1.value && Number(dataParams.amount) > Number(selectUserInfo.credit) && dataParams.ops == '2' && selectUserInfo.isShowCanUse != 1) {
        beyond.value = true
    } else if (showDialog1.value && Number(dataParams.amount) > Number(selectUserInfo.canUseLimit) && dataParams.ops == '2' && selectUserInfo.isShowCanUse == 1) {
        beyond.value = true
    } else if (showDialog2.value && Number(dataParams.amount) > Number(selectUserInfo.cash) && dataParams.ops == 2) {
        beyond.value = true
    } else {
        beyond.value = false
    }
}

const qdan = () => {
    let getDate = {
        accountId: dataParams.accountId,
        type: dataParams.type
    }
    ajax.drawall(getDate).then(res => {
        showdio.value = false
        closeDialog()
        getUserInfo()
        showToast({ type: res.code == 200 ? 'success' : 'error', message: res.message })
    })
}

const extractAll = (type) => {
    showdio.value = true
}

const confirmAmount = async(type) => {
    let that = this
    if (loading.value) {
        return false
    }
    loading.value = true
    setTimeout(() => {
        loading.value = false
    }, 3000)
    
    if (!dataParams.ops) {
        showToast({
            message: '请选择类型!',
            className: 'custom-toast',
            duration: 1000  // 自定义显示时间
        });
        return
    }
    
    if (dataParams.ops == 1) {
        if (dataParams.amount > upLevelAmount.value) {
            showToast({
                message: '输入的额度不能超过上级额度!',
                className: 'custom-toast',
                duration: 1000  // 自定义显示时间
            });
            return
        }
    }
    
    if (dataParams.ops == 2) {
        if (dataParams.amount > selectUserInfo.credit && type == 'creditAmount' && selectUserInfo.isShowCanUse != 1) {
            showToast({
                message: '输入的额度不能超过信用额度!',
                className: 'custom-toast',
                duration: 1000  // 自定义显示时间
            });
            return
        }
        if (dataParams.amount > selectUserInfo.canUseLimit && type == 'creditAmount' && selectUserInfo.isShowCanUse == 1) {
            showToast({
                message: '输入的额度不能超过信用额度!',
                className: 'custom-toast',
                duration: 1000  // 自定义显示时间
            });
            return
        }
        if (dataParams.amount > selectUserInfo.cash && type == 'cashAmount') {
            showToast({
                message: '输入的额度不能超过现金额度!',
                className: 'custom-toast',
                duration: 1000  // 自定义显示时间
            });
            return
        }
    }
    const res = await userStore.getQuotaupdate(dataParams)
    if (res.code == 200) {
        showToast({
            message: '操作成功!',
            className: 'custom-toast',
            duration: 1000  // 自定义显示时间
        });
        loading.value = false
        closeDialog()
        getUserInfo()
    }
}

const getUserInfo = async() => {
    try {
        yxlist.value = []
        const res = await userStore.getQueryOrg(props.id)
        userInfo.value = res.data
        
        if (res.data.handicapList.length > 0) {
            for (let j = 0; j < res.data.handicapList.length; j++) {
                if (res.data.handicapList[j] == 1) {
                    isA.value = true
                }
                if (res.data.handicapList[j] == 2) {
                    isB.value = true
                }
                if (res.data.handicapList[j] == 3) {
                    isC.value = true
                }
                if (res.data.handicapList[j] == 4) {
                    isD.value = true
                }
            }
        }
        
        ruleForm.id = props.id
        ruleForm.nickName = userInfo.value.nickName
        ruleForm.passwd = ''
        ruleForm.lotteryList = userInfo.value.lotteryList1
        ruleForm.status = userInfo.value.status
        ruleForm.account = userInfo.value.account
        ruleForm.handicap = userInfo.value.handicapList[0]
        ruleForm.mode = userInfo.value.mode
        ruleForm.lotlist = []
        ruleForm.opcpList = []
        ruleForm.layer = userInfo.value.layer
        ruleForm.share = ''
        
        if (userInfo.value.lotteryList1.length > 0) {
            yxlist.value = userInfo.value.lotteryList1
            res.data.lotteryList.map(items => {
                ruleForm.lotlist.push(items.lotteryId)
            })
            yxlist.value.map(item => {
                res.data.lotteryList.map(its => {
                    if (its.lotteryId == item.lotteryId && its.isNeed == 1) {
                        item.show = true
                    }
                })
            })
        }
        
        let t2 = ''
        res.data.occupyList.map(iten => {
            if (iten.isChange == 1) {
                t2 = 1
            }
        })
        userInfo.value.isChange = t2
        ruleForm.opcpList = res.data.occupyList
        
        if (!ruleForm.passwd) {
            rules.passwd[0].required = false
        }
    } catch (error) {
        console.log(error)
    }
}

const onSubmit = (formName) => {
    let that = this
    if (!ruleForm.passwd) {
        rules.passwd[0].required = false
    }
    let paw = ruleForm.passwd.toLowerCase()
    ruleForm.password = ruleForm.passwd ? proxy.$md5(paw + 'B!32$ACg@wev@fpo3.H9') : ''
    editMember()
}

const editMember = async() => {
    
    if (ruleForm.lotlist.length == 0) {
        showToast({ type: 'error', message: '至少要选择一个游戏' })
        return false
    }
    
    ruleForm.occupyList = []
    ruleForm.handicapList = []
    ruleForm.lotteryList = []
    
    let t = ''
    ruleForm.opcpList.map(iten => {
        if (iten.share < iten.pminShare || iten.share > iten.pmaxShare) {
            t = 1
            return false
        }
    })
    
    if (t) {
        showToast({
            type: 'error',
            message: '上级占成不能超过最大值或者最低值不能超过最高值'
        })
        return false
    }
    
    ruleForm.occupyList = ruleForm.opcpList
    
    const loadingToast = showLoadingToast({
        lock: true,
        duration: 0,
        forbidClick: true,
        mask: true,
        background: 'rgba(0, 0, 0, 0.7)',
        message: '正在加载……'
    })
    
    yxlist.value.map(item => {
        ruleForm.lotlist.map(items => {
            if (item.lotteryId == items) {
                ruleForm.lotteryList.push(item)
            }
        })
    })
    
    ruleForm.handicapList.push(ruleForm.handicap)
    ruleForm.role = userInfo.value.role
    loading.value = true
    
    setTimeout(function () {
        loadingToast.close()
    }, 5000)
    try {
        const res = await userStore.orgUpdate(ruleForm)
        loading.value = false
        loadingToast.close()
        showToast({
            message: '修改成功',
            className: 'custom-toast',
            duration: 2000  // 自定义显示时间
        });
        if (res.code == 200) {
            router.push({ name: 'UserManage', params: { pid: userInfo.value.pid } })
        }
    } catch (error) {
        console.log('修改失败')
    }
}

const cancelForm = () => {
    router.push({ name: 'UserManage', params: { pid: userInfo.value.pid } })
}

// ==================== 生命周期 ====================
onMounted(() => {
    getUserInfo()
})
</script>
